import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"繁荣度与活跃度","description":"","frontmatter":{},"headers":[],"relativePath":"towns/Advancements.md","filePath":"towns/Advancements.md"}'),o={name:"towns/Advancements.md"};function n(s,t,h,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="繁荣度与活跃度" tabindex="-1">繁荣度与活跃度 <a class="header-anchor" href="#繁荣度与活跃度" aria-label="Permalink to &quot;繁荣度与活跃度&quot;">​</a></h1><p>联盟的<strong>活跃度</strong>（繁荣度）反映联盟的整体活跃程度，由成员的日常活动积累而来，<strong>无法用钻石购买</strong>。活跃度按 <strong>7 日滚动窗口</strong>统计，不活跃会自动回落——活跃是持续经营的事，没有一劳永逸的档位。</p><h2 id="活跃度来源" tabindex="-1">活跃度来源 <a class="header-anchor" href="#活跃度来源" aria-label="Permalink to &quot;活跃度来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>怎么获得</th><th>计分</th><th>每日上限</th><th>备注</th></tr></thead><tbody><tr><td><strong>基线</strong></td><td>成员任意位置在线（野外也算）</td><td>每分钟 +0.5</td><td>每人 10</td><td>5 分钟无移动不计；在联盟领地内时按「驻留」计，不叠加</td></tr><tr><td><strong>生产</strong></td><td>在联盟领地内放置/破坏方块</td><td>每 10 个方块 +1</td><td>每盟 30</td><td>建造、收割、挖矿同计</td></tr><tr><td><strong>狩猎</strong></td><td>在联盟领地内击杀敌对生物</td><td>每 5 只 +1</td><td>每盟 30</td><td>必须有击杀者的击杀才计（摔死等不计）</td></tr><tr><td><strong>驻留</strong></td><td>在联盟领地（含子领地）内在线</td><td>每分钟 +1</td><td>每人 20 / 每盟 60</td><td>5 分钟无移动不计</td></tr><tr><td><strong>接待</strong></td><td>非本盟访客当日首次进入领地</td><td>每位访客 +5</td><td>每盟 30</td><td>同一访客当日只计一次</td></tr></tbody></table><p><strong>效率提示</strong>：待在联盟领地里的效率是野外的 <strong>2 倍以上</strong>——生产、狩猎、接待只在领地内计分，驻留速率也比基线高一倍。</p><h2 id="防滥用" tabindex="-1">防滥用 <a class="header-anchor" href="#防滥用" aria-label="Permalink to &quot;防滥用&quot;">​</a></h2><p>活跃度设有多重防滥用规则，挂机刷分无效：</p><ul><li><strong>AFK 判定</strong>：5 分钟无移动视为挂机，基线/驻留不计分。</li><li><strong>领地限定</strong>：生产、狩猎、驻留、接待都必须在联盟领地内才计；家园领地不计。</li><li><strong>击杀归属</strong>：只有有击杀者的击杀才计，摔死/岩浆死等环境死亡不计。</li><li><strong>访客去重</strong>：同一访客当日只计一次；同一 IP 的账号当日也只计一次。</li><li><strong>每日上限</strong>：每个来源都有独立上限，驻留/基线另有每人上限。</li></ul><h2 id="档位" tabindex="-1">档位 <a class="header-anchor" href="#档位" aria-label="Permalink to &quot;档位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>图标</th><th>活跃度阈值</th></tr></thead><tbody><tr><td><strong>铜锭</strong></td><td>铜锭</td><td>200</td></tr><tr><td><strong>铁锭</strong></td><td>铁锭</td><td>450</td></tr><tr><td><strong>金锭</strong></td><td>金锭</td><td>800</td></tr><tr><td><strong>下界之星</strong></td><td>下界之星</td><td>1200</td></tr><tr><td><strong>沉眠</strong></td><td>灰色染料</td><td>长期无活跃自动回落</td></tr></tbody></table><ul><li><strong>滚动衰减</strong>：活跃度只统计最近 7 天，活跃度回落时档位自动降级。</li><li><strong>降档不没收</strong>：低于阈值只是暂停特权、领地之心变暗，领地与资产不受影响；恢复活跃即可回到原档位。</li></ul><h2 id="查看活跃度" tabindex="-1">查看活跃度 <a class="header-anchor" href="#查看活跃度" aria-label="Permalink to &quot;查看活跃度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim prosperity</code></td><td>查看联盟活跃度各来源上限与档位阈值</td></tr><tr><td><code>/gclaim top</code></td><td>查看全服活跃榜</td></tr></tbody></table><h2 id="领地之心" tabindex="-1">领地之心 <a class="header-anchor" href="#领地之心" aria-label="Permalink to &quot;领地之心&quot;">​</a></h2><p>把满级信标注册为联盟的<strong>领地之心</strong>（灯塔），档位越高效果越强：</p><table tabindex="0"><thead><tr><th>档位</th><th>效果槽</th><th>范围</th><th>光柱颜色</th></tr></thead><tbody><tr><td>沉眠</td><td>0（熄灭）</td><td>—</td><td>红</td></tr><tr><td>铜锭</td><td>1</td><td>原版</td><td>琥珀</td></tr><tr><td>铁锭</td><td>2</td><td>原版</td><td>银</td></tr><tr><td>金锭</td><td>2</td><td>×1.5</td><td>金</td></tr><tr><td>下界之星</td><td>3</td><td>×2.0</td><td>青</td></tr></tbody></table><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim heart register</code></td><td>把脚下满级信标注册为领地之心</td></tr><tr><td><code>/gclaim heart unregister</code></td><td>注销领地之心</td></tr><tr><td><code>/gclaim heart effect</code></td><td>查看/切换特效</td></tr><tr><td><code>/gclaim heart info</code></td><td>查看领地之心信息</td></tr><tr><td><code>/gclaim heart public on/off</code></td><td>开关公开传送（铁锭档位以上）</td></tr></tbody></table><h2 id="与联盟等级的关系" tabindex="-1">与联盟等级的关系 <a class="header-anchor" href="#与联盟等级的关系" aria-label="Permalink to &quot;与联盟等级的关系&quot;">​</a></h2><p>联盟活跃度会联动上报给<a href="./#等级与经验">联盟</a>系统<strong>转化为联盟经验</strong>——升档时按跨度折算经验，帮助联盟升级、提升成员上限：越活跃的联盟越强大。</p>',19)])])}const m=d(o,[["render",n]]);export{b as __pageData,m as default};
